#!/bin/bash
# job_en.sh -- English-materials rerun (PROBE_LANG=en) of the whole Llama-3.1-8B stack (2026-10-24).
# Everything the Chinese run established, redone with English, generic materials (NOTES.md scenario, everyday
# assistance instead of AI-self talk) so the two can be compared cell by cell.
# Stage 1: English filler (coding + general) generated by the model itself, GPUs 0 and 1.
# Stage 2, one queue per GPU:
#   GPU0  X20k cross cells (content x wrapper x self-contamination), seeds 1-5  ->  logit lens  ->  heads (instruct)
#   GPU1  T=1 sampling general m13 -> m10  ->  logit lens  ->  heads (base checkpoint, instruct tokenizer)
#   GPU2  T=1 sampling coding c13 -> c10   ->  context-length series X8k/X32k/X64k (instruct), seeds 1-3
#   GPU3  controls at 32k (Q trigger shapes / R read-in / P paren / S placement) + self-approval K20k, seeds 1-3
#         ->  contamination variants (instruct, then base)
# Launch on the GPU server inside tmux:
#   tmux new-session -d -s opus_en 'bash job_en.sh 2>&1 | tee results/job_en.log'
cd ${PHANTOM_ROOT:?set PHANTOM_ROOT to this code directory} || exit 1
log() { echo "[$(date '+%F %T')] $*"; }
DOCKER="docker run --rm --gpus all --ipc=host -v $PHANTOM_ROOT:$PHANTOM_ROOT -v $MODEL_ROOT:$MODEL_ROOT:ro -e HF_HUB_OFFLINE=1 -e TRANSFORMERS_OFFLINE=1 -e PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True -e PROBE_LANG=en -w ${PHANTOM_ROOT:?set PHANTOM_ROOT to this code directory}"
IMG=${IMG:?set IMG to a PyTorch container image, see README}
MD=${MODEL_ROOT:?set MODEL_ROOT to the model directory}
M=$MD/Llama-3.1-8B-Instruct
MB=$MD/Llama-3.1-8B
FILL="--filler-coding results/filler_en_coding.jsonl --filler-meta results/filler_en_general.jsonl"
X="X20k_c00 X20k_c10 X20k_c13 X20k_m00 X20k_m10 X20k_m13"
LEN="X8k_m10 X8k_m13 X8k_c13 X32k_m10 X32k_m13 X32k_c13 X64k_m10 X64k_m13 X64k_c13"
CTRL="Q32k_m10_q Q32k_c10_q Q32k_m00_q Q32k_c00_q Q32k_m10_n Q32k_m10_qn Q32k_m10_e Q32k_m10_s10 Q32k_m10_s30 Q32k_m10_i \
R32k_m10_tr R32k_c10_tr R32k_m00_tr R32k_m10_bn R32k_c10_bn R32k_m10_trp R32k_m10_bnp P32k_m10_paren P32k_m13_paren \
S32k_m10_str S32k_c10_str S32k_m10_sbn S32k_m10_aq S32k_m10_aq3 S32k_m10_aqu S32k_c10_aq \
K20k_c0 K20k_c4 K20k_c4w K20k_m4w K20k_c8 K20k_c4n"
MECH="$FILL --conditions X20k_m10 X20k_m13 X20k_c10 X20k_c13 --seeds 1 2 3"
E2E="python e2e_sample.py --model $M $FILL --target-tokens 20000 --seeds 1 2 3 4 5 --n-first 20000 --n-full 32 --batch 8 --max-new 200 --max-hit-cont 3"

probe() {  # gpu out-name seeds... : turn_boundary_probe over $COND with forced-'user' continuation
  local gpu=$1 name=$2; shift 2
  for s in "$@"; do
    $DOCKER -e CUDA_VISIBLE_DEVICES=$gpu $IMG python turn_boundary_probe.py --model $M $FILL --force-first user --max-forced 48 \
        --conditions $COND --filler-seed $s --out results/$name.jsonl >> results/$name.log 2>&1 || log "FAILED $name seed $s -- see results/$name.log"
  done
  log "$name done ($(wc -l < results/$name.jsonl 2>/dev/null) records)"
}
mech() {  # gpu script tag model-dir tokenizer-dir
  local gpu=$1 script=$2 tag=$3 mdir=$4 tdir=$5
  local out=results/en_${script%.py}_$tag
  $DOCKER -e CUDA_VISIBLE_DEVICES=$gpu $IMG python $script --model $mdir --tokenizer $tdir $MECH --tag $tag --out $out.jsonl > $out.log 2>&1 \
      && log "$script $tag done ($(wc -l < $out.jsonl) records)" || log "FAILED $script $tag -- see $out.log"
}

log "stage 1: English filler (coding on GPU0, general on GPU1)"
( $DOCKER -e CUDA_VISIBLE_DEVICES=0 $IMG python make_filler.py --model $M --kind coding --n 320 \
      --out results/filler_en_coding.jsonl > results/filler_en_coding.log 2>&1 || log "FAILED filler coding" ) &
( $DOCKER -e CUDA_VISIBLE_DEVICES=1 $IMG python make_filler.py --model $M --kind meta --n 400 \
      --out results/filler_en_general.jsonl > results/filler_en_general.log 2>&1 || log "FAILED filler general" ) &
wait
for f in results/filler_en_coding.jsonl results/filler_en_general.jsonl; do
  [ -s "$f" ] || { log "missing $f -- abort"; exit 1; }
  log "$f: $(wc -l < "$f") pairs"
done
log "stage 1 done"

log "stage 2: four GPU queues"
( COND=$X probe 0 en_cross_Llama-3.1-8B-Instruct 1 2 3 4 5
  mech 0 logit_lens.py Llama-3.1-8B-Instruct $M $M
  mech 0 head_attrib.py Llama-3.1-8B-Instruct $M $M
  log "GPU0 queue done" ) &
( $DOCKER -e CUDA_VISIBLE_DEVICES=1 $IMG $E2E --kind meta --wrapper 1 --contam-k 3 --tag en_m13 --out results/en_e2e_m13.jsonl > results/en_e2e_m13.log 2>&1 || log "FAILED e2e m13"
  $DOCKER -e CUDA_VISIBLE_DEVICES=1 $IMG $E2E --kind meta --wrapper 1 --contam-k 0 --tag en_m10 --out results/en_e2e_m10.jsonl > results/en_e2e_m10.log 2>&1 || log "FAILED e2e m10"
  log "e2e general done"
  mech 1 logit_lens.py Llama-3.1-8B-Base $MB $M
  mech 1 head_attrib.py Llama-3.1-8B-Base $MB $M
  log "GPU1 queue done" ) &
( $DOCKER -e CUDA_VISIBLE_DEVICES=2 $IMG $E2E --kind coding --wrapper 1 --contam-k 3 --tag en_c13 --out results/en_e2e_c13.jsonl > results/en_e2e_c13.log 2>&1 || log "FAILED e2e c13"
  $DOCKER -e CUDA_VISIBLE_DEVICES=2 $IMG $E2E --kind coding --wrapper 1 --contam-k 0 --tag en_c10 --out results/en_e2e_c10.jsonl > results/en_e2e_c10.log 2>&1 || log "FAILED e2e c10"
  log "e2e coding done"
  COND=$LEN probe 2 en_length_Llama-3.1-8B-Instruct 1 2 3
  log "GPU2 queue done" ) &
( COND=$CTRL probe 3 en_controls_Llama-3.1-8B-Instruct 1 2 3
  $DOCKER -e CUDA_VISIBLE_DEVICES=3 $IMG python contam_variants.py --model $M --tokenizer $M $FILL --seeds 1 2 3 \
      --out results/en_contam_variants_Llama-3.1-8B-Instruct.jsonl > results/en_contam_variants_Llama-3.1-8B-Instruct.log 2>&1 || log "FAILED variants instruct"
  $DOCKER -e CUDA_VISIBLE_DEVICES=3 $IMG python contam_variants.py --model $MB --tokenizer $M $FILL --seeds 1 2 3 \
      --out results/en_contam_variants_Llama-3.1-8B-Base.jsonl > results/en_contam_variants_Llama-3.1-8B-Base.log 2>&1 || log "FAILED variants base"
  log "GPU3 queue done" ) &
wait
log "EN JOB DONE"
